export const PLZ_DB=(()=>{const p={},o={};PLZ_RAW.split("|").forEach(e=>{const[z,n,b]=e.split(",");p[z]={ort:n,bl:b};const k=n.toLowerCase();if(!o[k])o[k]=[];o[k].push({plz:z,ort:n,bl:b})});return{byPlz:p,byOrt:o,allOrts:Object.keys(o).sort()}})();
// ── Kappungsgrenze 15%: dynamisch aus CSV geladen ──
let kapp15Set=new Set();
(async()=>{
  try{
    const res=await fetch("/staedte-mit-kappungsgrenze.csv");
    const txt=await res.text();
    kapp15Set=new Set(
      txt.split("\n")
        .map(l=>l.trim().split(";"))
        .filter(p=>p.length>=2&&p[1]&&p[1]!=="Keine Kappungsgrenze")
        .map(p=>p[1].toLowerCase().trim())
    );
  }catch(e){console.warn("[kapp15] CSV nicht geladen:",e);}
})();
export const isK15=o=>o?kapp15Set.has(o.toLowerCase().trim()):false;
